    def delete(self, key):
        # Buggy: raises KeyError if key not in memtable
        if self.memtable.get(key) is None:
            raise KeyError(key)
        with open(self.wal_path, "a", encoding="utf-8") as f:
            f.write(serialize_entry("DEL", key))
        self.memtable.delete(key)

